interface PrefixParselet { Expr parse(Parser p, Token t); }
interface InfixParselet  { Expr parse(Parser p, Expr left, Token t); int precedence(); }
private final Map<TokenType, PrefixParselet> prefixes = new EnumMap<>(TokenType.class);
private final Map<TokenType, InfixParselet>  infixes  = new EnumMap<>(TokenType.class);

Expr parseExpression(int minPrec) {
    Token t = consume();
    Expr left = prefixes.get(t.type).parse(this, t);        // null denotation
    while (minPrec < precedenceOf(peek()))                  // left denotation
        left = infixes.get(consume().type).parse(this, left, previous());
    return left;
}
